                      RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights, BigDecimal subtotal,
                      BigDecimal discount, BigDecimal total) {
    public static final String TITLE = "Comprovante de reserva";
    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");

    public static Receipt of(Reservation r, Room room) {
        Quote q = r.quote();
        return new Receipt(TITLE, r.id(), r.guestName(), r.guestCpf(), room.number(), room.type(), r.checkIn(),
                r.checkOut(), q.nights(), q.subtotal(), q.discount(), q.total());
    }

